  // Adminer (INSTALL_DBTOOL) is retired — Nxeon DB Studio is the only DB manager now.
  // Hide its task rows entirely, incl. stale FAILED ones (e.g. the old download 404),
  // so a dead fallback never surfaces an error on the account overview.
  const visible = tasks.filter((t) => t.kind !== "INSTALL_DBTOOL" && (t.status !== "DONE" || t.result || t.error));
  if (!visible.length) return null;
